args.query:
\dt api.*
\dv api.*
select table_name,column_name,data_type,is_nullable,column_default from information_schema.columns where table_schema in ('api','public') order by table_schema,table_name,ordinal_position;
select * from api.app_user;
select * from api.company;

select n.nspname,p.proname,pg_get_functiondef(p.oid) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('api','public') ;
select tgname,tgrelid::regclass,pg_get_triggerdef(oid) from pg_trigger where not tgisinternal;
select schemaname,tablename,policyname,cmd,roles,qual,with_check from pg_policies;
select relname,relrowsecurity,relforcerowsecurity,relkind from pg_class where relnamespace='api'::regnamespace;

select p.proname,pg_get_functiondef(p.oid) from pg_proc p where pronamespace='private'::regnamespace;
select grantee,table_name,privilege_type,column_name from information_schema.column_privileges where table_schema='api' and grantee not in ('postgres') order by 2,1,4;
select grantee,table_name,privilege_type from information_schema.table_privileges where table_schema='api' and grantee not in ('postgres') order by 2,1;
select * from api.status order by ord;

